  function t(k, v) { var s = TR[LG][k] || TR.en[k] || k; return v ? s.replace(/\{(\w+)\}/g, function (m, x) { return v[x] != null ? v[x] : m; }) : s; }
  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function tx(k, v) { var o = {}; if (v) Object.keys(v).forEach(function (x) { o[x] = esc(v[x]); }); return t(k, v ? o : null); }   // translated, with escaped values
  if (LG !== 'en') { document.documentElement.lang = LG; if (LG === 'ar') { var mn = document.getElementById('main'); if (mn) mn.dir = 'rtl'; } }
  document.querySelectorAll('[data-i]').forEach(function (e) { var k = e.getAttribute('data-i'); if (TR[LG][k]) e.textContent = TR[LG][k]; });
